<template>
<section class="support-panel" :class="{'support-panel--mobile':mobile,'content-card':!mobile}" v-loading="loading">
  <aside v-if="!mobile || showHistory" class="support-panel__history" :class="{'is-drawer':mobile}"><header v-if="mobile"><strong>会话记录</strong><button type="button" @click="showHistory=false">完成</button></header><button class="support-new" type="button" :disabled="starting" @click="startConversation">＋ 发起新咨询</button><button v-for="item in conversations" :key="item.id" class="support-panel__session" :class="{active:current?.id===item.id}" @click="selectConversation(item.id);showHistory=false"><strong>{{ item.title }}</strong><small>{{ item.conversation_closed ? '已结束 · 可查看记录' : modeLabels[item.handling_mode] }}</small></button></aside>
  <main class="support-panel__main"><header class="support-panel__header"><button v-if="mobile" type="button" class="support-back" aria-label="返回消息列表" @click="$emit('back')">‹</button><div><h2>售后客服</h2><p>{{ current?.conversation_closed ? '会话已结束，记录已保留' : modeLabels[current?.handling_mode || 'ai'] }}</p></div><div class="support-header-actions"><button v-if="current && !current.conversation_closed && current.handling_mode==='ai'" type="button" :disabled="requestingHuman" @click="requestHuman">申请人工</button><button v-if="current && !current.conversation_closed && ['human','human_requested'].includes(current.handling_mode)" type="button" :disabled="closing || sending" @click="endSession">结束人工</button><button v-if="mobile" type="button" @click="showHistory=true">记录</button></div></header>
    <div class="support-message-wrap"><div ref="messageList" class="support-panel__messages" @scroll="onScroll" role="log" aria-label="客服聊天记录" aria-live="polite"><div ref="messageContent" class="support-message-content"><div v-if="!current?.messages?.length" class="support-panel__welcome">你好，我是 AI 客服。可以向我咨询商品、订单和售后问题，未解决时可申请人工协助。</div><article v-for="message in current?.messages || []" :key="message.id" class="support-panel__message" :class="{mine:message.sender_role==='customer',system:message.sender_role==='system'}"><template v-if="message.sender_role==='system'"><p>{{ message.content }}</p></template><template v-else><div class="support-avatar">{{ message.sender_role==='customer' ? '我' : '服' }}</div><div class="support-bubble"><small>{{ message.sender_role==='customer' ? '我' : message.sender_name }}</small><p>{{ message.content }}</p><time>{{ message.create_time.replace('T',' ').slice(0,19) }}</time></div></template></article><p v-if="thinking" class="support-panel__thinking">AI 客服正在回复…</p></div></div><button v-if="!pinned" type="button" class="support-latest" @click="scrollToLatest">{{ unseen ? `${unseen} 条新消息 · ` : '' }}回到最新 ↓</button></div>
    <div v-if="error || aiError" class="support-panel__error">{{ error || aiError }}<button v-if="current?.handling_mode==='ai' && !current.conversation_closed && !thinking" @click="retryAI">重试</button></div>
    <form v-if="current && !current.conversation_closed" ref="composer" class="support-panel__composer" @submit.prevent="send"><div class="support-input-row"><textarea ref="input" v-model="draft" rows="2" maxlength="2000" placeholder="输入消息…" enterkeyhint="send" @keydown="onKeydown" /><button type="submit" :disabled="!draft.trim() || sending || thinking || closing">{{ sending ? '发送中' : '发送' }}</button></div><p>{{ current.handling_mode==='ai' ? 'AI 接待中 · 不满意可申请人工' : current.handling_mode==='human' ? '人工客服接待中' : '已申请人工，等待接待' }}</p></form>
    <div v-else-if="current?.conversation_closed" class="support-closed"><span>本次人工会话已结束</span><button type="button" :disabled="starting" @click="startConversation">发起新咨询</button></div>
  </main>
</section>
</template>
<script setup>
import {nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
const props=defineProps({conversationId:Number,mobile:Boolean})
defineEmits(['back'])
const loading=ref(false),conversations=ref([]),current=ref(null),draft=ref(''),sending=ref(false),thinking=ref(false),requestingHuman=ref(false),closing=ref(false),starting=ref(false),error=ref(''),aiError=ref(''),showHistory=ref(false),pinned=ref(true),unseen=ref(0)
const messageList=ref(null),messageContent=ref(null),input=ref(null),composer=ref(null)
const modeLabels={ai:'AI 客服接待中',human_requested:'已申请人工，等待接待',human:'人工客服已接入'}
const url=(id,suffix='')=>`/api/customer/support/conversations/${id}${suffix}`
let timer,sequence=0,disposed=false,polling=false,observer
function updated(){window.dispatchEvent(new Event('customer-messages-updated'))}
async function scrollToLatest(){await nextTick();if(messageList.value)messageList.value.scrollTop=messageList.value.scrollHeight;pinned.value=true;unseen.value=0}
function onScroll(){const el=messageList.value;if(!el)return;pinned.value=el.scrollHeight-el.scrollTop-el.clientHeight<55;if(pinned.value)unseen.value=0}
async function refreshList(){const result=await request.get('/api/customer/support/conversations');if(!disposed)conversations.value=result.data || []}
async function selectConversation(id){const version=++sequence;loading.value=true;error.value='';if(current.value?.id!==id)draft.value='';try{const result=await request.get(url(id));if(version!==sequence||disposed)return;current.value=result.data;thinking.value=!!result.data.ai_pending;aiError.value=result.data.ai_error || '';await scrollToLatest();updated()}catch(e){if(!disposed)error.value=e.message || '读取会话失败'}finally{if(version===sequence)loading.value=false}}
async function startConversation(){if(starting.value)return;starting.value=true;try{const result=await request.post('/api/customer/support/conversations');await selectConversation(result.data.id);await refreshList();showHistory.value=false}catch(e){error.value=e.message || '创建咨询失败'}finally{starting.value=false}}
async function send(){const content=draft.value.trim(),id=current.value?.id;if(!content||!id||sending.value||thinking.value||closing.value||current.value.conversation_closed)return;const version=++sequence;sending.value=true;error.value='';try{const result=await request.post(url(id,'/messages'),{content});if(disposed||current.value?.id!==id||version!==sequence)return;if(!current.value.messages.some(m=>m.id===result.data.message.id))current.value.messages.push(result.data.message);if(draft.value.trim()===content)draft.value='';thinking.value=!!result.data.ai_pending;await scrollToLatest();if(composer.value?.contains(document.activeElement))input.value?.focus({preventScroll:true});updated();await refreshList()}catch(e){if(!disposed)error.value=e.message || '发送失败'}finally{sending.value=false}}
function onKeydown(event){if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&event.keyCode!==229){event.preventDefault();send()}}
async function requestHuman(){if(!current.value||requestingHuman.value)return;const id=current.value.id,version=++sequence;requestingHuman.value=true;try{const result=await request.post(url(id,'/human'),{reason:'对AI回答不满意，希望人工客服协助'});if(disposed||version!==sequence)return;current.value=result.data;thinking.value=false;error.value='';aiError.value='';await scrollToLatest();await refreshList();updated()}catch(e){error.value=e.message || '申请失败'}finally{requestingHuman.value=false}}
async function endSession(){if(!current.value||closing.value)return;try{await ElMessageBox.confirm('结束后不能继续在本次会话中发消息，聊天记录会保留。未完成的退款或换货仍按原流程处理。','结束人工服务',{confirmButtonText:'结束服务',cancelButtonText:'继续沟通'});closing.value=true;const id=current.value.id,version=++sequence;const result=await request.post(url(id,'/close'),{reason:'问题已解决或不再需要人工服务'});if(disposed||version!==sequence)return;current.value=result.data;thinking.value=false;error.value='';aiError.value='';await scrollToLatest();await refreshList();updated()}catch(e){if(e!=='cancel'&&e!=='close')error.value=e.message || '结束会话失败'}finally{closing.value=false}}
async function retryAI(){if(!current.value||thinking.value||current.value.conversation_closed)return;try{const result=await request.post(url(current.value.id,'/ai-prepare'));thinking.value=!!result.data.ai_pending;error.value='';aiError.value=''}catch(e){error.value=e.message || '重试失败'}}
watch(()=>props.conversationId,id=>{if(id&&id!==current.value?.id)selectConversation(id)})
onMounted(async()=>{try{await refreshList();if(disposed)return;if(props.conversationId)await selectConversation(props.conversationId);else await startConversation()}catch(e){error.value=e.message || '读取咨询失败'}if(disposed)return;await nextTick();if(disposed)return;observer=new ResizeObserver(()=>{if(pinned.value&&messageList.value)messageList.value.scrollTop=messageList.value.scrollHeight});if(messageContent.value)observer.observe(messageContent.value);if(messageList.value)observer.observe(messageList.value);timer=setInterval(async()=>{if(disposed||document.hidden||!current.value||loading.value||polling||sending.value||closing.value||requestingHuman.value)return;polling=true;const id=current.value.id,version=sequence,before=new Set(current.value.messages.map(m=>m.id));try{const result=await request.get(url(id));if(disposed||version!==sequence||current.value?.id!==id)return;const added=result.data.messages.filter(m=>!before.has(m.id)).length;current.value=result.data;thinking.value=!!result.data.ai_pending;aiError.value=result.data.ai_error || '';if(added){if(pinned.value)await scrollToLatest();else unseen.value+=added;updated()}}catch{}finally{polling=false}},3500)})
onBeforeUnmount(()=>{disposed=true;++sequence;clearInterval(timer);observer?.disconnect()})
</script>
<style scoped>
.support-panel{display:grid;grid-template-columns:230px minmax(0,1fr);height:min(700px,calc(100dvh - 230px));min-height:400px;padding:0;overflow:hidden}.support-panel__history{display:flex;flex-direction:column;gap:10px;min-height:0;padding:14px;overflow:auto;border-right:1px solid #edf0f3;background:#fff}.support-panel__session{padding:12px;border:1px solid #e8edf3;border-radius:9px;background:#fff;text-align:left;cursor:pointer}.support-panel__session.active{border-color:#f0b39f;background:#fff5ef}.support-panel__session strong{display:block;font-size:13px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.support-panel__session small{display:block;margin-top:7px;color:#9ba6b0;font-size:11px}.support-new{min-height:42px;flex:none;padding:8px;border:1px solid #e8d3c8;border-radius:9px;background:#fff8f2;color:#d08865;font-size:12px;cursor:pointer}.support-panel__main{display:flex;flex-direction:column;min-height:0;min-width:0;overflow:hidden;background:#fff}.support-panel__header{display:flex;align-items:center;gap:10px;min-height:60px;flex:none;padding:12px 16px;border-bottom:1px solid #eff1f4}.support-panel__header>div:first-of-type{flex:1;min-width:0}.support-panel__header h2{margin:0;font-size:15px;font-weight:600}.support-panel__header p{margin:5px 0 0;color:#9da7b1;font-size:10px}.support-header-actions{display:flex;gap:6px;align-items:center}.support-header-actions>button{min-height:40px;padding:5px 9px;border:1px solid #e5eaf0;border-radius:15px;background:#fff;color:#8e9ba7;font-size:11px;cursor:pointer;white-space:nowrap}.support-back{width:24px;min-height:40px;padding:0;border:0;background:none;font-size:28px;color:#8796a3}.support-message-wrap{position:relative;display:flex;flex:1;min-height:0;overflow:hidden;background:#f5f6f8}.support-panel__messages{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;overflow-anchor:none;-webkit-overflow-scrolling:touch;touch-action:pan-y;scrollbar-width:thin}.support-message-content{display:flex;flex-direction:column;gap:20px;padding:18px 14px 28px}.support-panel__welcome{padding:16px;border-radius:12px;background:#fff;line-height:1.85;font-size:13px;color:#8999a6}.support-panel__message{display:flex;gap:8px;align-items:flex-start;min-width:0}.support-avatar{display:grid;place-items:center;flex:none;width:30px;height:30px;border-radius:50%;background:#fff;color:#c4a6b4;font-size:12px}.support-bubble{display:flex;flex-direction:column;gap:5px;max-width:calc(100% - 48px);min-width:0}.support-bubble small{font-size:10px;color:#a1acb7}.support-bubble>p{margin:0;padding:10px 13px;border:1px solid #edf0f3;border-radius:2px 12px 12px;background:#fff;font-size:14px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;color:#405463}.support-bubble time{font-size:9px;color:#aeb7bf}.support-panel__message.mine{flex-direction:row-reverse}.mine .support-bubble{align-items:flex-end}.mine .support-bubble>p{background:#ffede4;border-color:#f6dccc;border-radius:12px 2px 12px 12px}.mine .support-avatar{background:#f2bfa5;color:#fff}.support-panel__message.system{justify-content:center;padding:0 16px}.support-panel__message.system>p{max-width:100%;padding:5px 9px;border-radius:5px;background:#eaeef2;color:#9aa6b1;font-size:10px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;margin:0;text-align:center}.support-panel__thinking{font-size:11px;color:#cca38b;margin:0}.support-latest{position:absolute;bottom:12px;right:12px;padding:8px 12px;border:1px solid #f1d7c8;border-radius:18px;background:#fff;color:#c59275;font-size:11px;box-shadow:0 2px 10px #9f765617}.support-panel__composer{flex:none;padding:10px 12px calc(8px + env(safe-area-inset-bottom));border-top:1px solid #e9edf1;background:#fff}.support-input-row{display:flex;gap:8px;align-items:flex-end}.support-input-row>textarea{flex:1;width:0;height:64px;max-height:100px;resize:none;border:1px solid #e5eaee;border-radius:10px;padding:9px 11px;color:#405463;background:#f9fafb;font-size:16px;line-height:1.5;outline:none}.support-input-row>textarea:focus{border-color:#efc3ad;background:#fff}.support-input-row>textarea::placeholder{color:#b4bdc5}.support-input-row>button{min-width:60px;height:40px;flex:none;border:0;border-radius:20px;color:#fff;background:#ed6957;font-size:13px}.support-input-row>button:disabled{opacity:.4}.support-panel__composer>p{margin:7px 0 0;font-size:9px;color:#b1bac2}.support-panel__error{flex:none;padding:8px 12px;color:#d48a7a;background:#fff2ef;font-size:11px;line-height:1.6}.support-panel__error>button{margin-left:8px;border:0;background:none;color:#cb785f}.support-closed{display:flex;flex:none;align-items:center;justify-content:space-between;gap:10px;padding:14px 16px calc(14px + env(safe-area-inset-bottom));border-top:1px solid #eef1f3;color:#a4afb8;font-size:11px}.support-closed>button{min-height:38px;padding:6px 15px;border:0;border-radius:20px;background:#ed6957;color:#fff;font-size:12px}.support-panel--mobile{height:100%;min-height:0;display:flex;border:0;border-radius:0;box-shadow:none;position:relative}.support-panel--mobile .support-panel__main{width:100%;height:100%}.is-drawer{position:absolute;inset:0 0 0 auto;z-index:5;width:85%;box-shadow:-8px 0 30px #22384f24}.is-drawer>header{display:flex;align-items:center;justify-content:space-between;min-height:40px;font-size:14px}.is-drawer>header button{border:0;background:none;color:#da997b;padding:10px;font-size:12px}@media(max-width:800px){.support-panel:not(.support-panel--mobile){grid-template-columns:1fr}.support-panel:not(.support-panel--mobile) .support-panel__history{display:none}}
</style>
